begin;
do $$
declare admin_id uuid; actor uuid; branch uuid; other uuid; product uuid; previous uuid; first_saved uuid; second_saved uuid; completed uuid; ready_order uuid; state jsonb; payload jsonb; original jsonb; changed jsonb; item jsonb; denied boolean; day date:=(now() at time zone 'America/Toronto')::date; stock integer;
begin
 select id into admin_id from public.profiles where role::text='CENTRAL_ADMIN' and status::text='active' limit 1;
 select id into actor from public.profiles where role::text='BRANCH_MANAGER' and status::text='active' limit 1;
 if actor is null then raise exception 'An active manager is required.';end if;
 insert into public.locations(name,is_central) values('Stock flow test (rolled back)',false) returning id into branch;
 insert into public.locations(name,is_central) values('Other stock flow test (rolled back)',false) returning id into other;
 update public.profiles set location_id=branch where id=actor;
 insert into public.catalog_items(name,category,unit_type,default_price,available_stock,is_active) values('Stock flow product (rolled back)','Pantry','Bucket',2,100,true) returning id into product;
 insert into public.branch_inventory_counts(location_id,count_date,submitted_by,submitted_name,flow_version,received_until) values(branch,day-1,actor,'Previous updater',2,day::timestamp at time zone 'America/Toronto') returning id into previous;
 insert into public.branch_inventory_lines(count_id,item_id,item_name,unit_type,quantity,opening_quantity,received_quantity,used_quantity,wasted_quantity,adjustment_quantity)
 select previous,id,name,unit_type::text,case when id=product then 5 else 0 end,case when id=product then 5 else 0 end,0,0,0,0 from public.catalog_items where is_active is true;
 insert into public.orders(location_id,order_number) values(branch,-2147483101) returning id into completed;
 insert into public.order_lines(order_id,item_id,quantity,fulfilled_quantity,unit_price,is_taxable,line_total) values(completed,product,4,4,2,false,8);
 insert into public.orders(location_id,order_number) values(branch,-2147483102) returning id into ready_order;
 insert into public.order_lines(order_id,item_id,quantity,fulfilled_quantity,unit_price,is_taxable,line_total) values(ready_order,product,8,8,2,false,16);
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 update public.orders set status='READY' where id in (completed,ready_order);
 select available_stock into stock from public.catalog_items where id=product;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 perform public.submit_pickup(completed,jsonb_build_array(jsonb_build_object('line_id',(select id from public.order_lines where order_id=completed),'quantity',4)),'',false);
 execute 'set local role authenticated';
 state:=public.branch_inventory_workspace(day);
 select value into item from jsonb_array_elements(state->'items') where value->>'id'=product::text;
 if (item->>'opening_quantity')::integer<>5 or (item->>'received_quantity')::integer<>4 or (item->>'quantity')::integer<>9 then raise exception 'Opening or completed-only receipts incorrect';end if;
 select jsonb_agg(jsonb_build_object('item_id',value->>'id','opening_quantity',(value->>'opening_quantity')::integer,'expected_opening_quantity',(value->>'opening_quantity')::integer,'expected_received_quantity',(value->>'received_quantity')::integer,'used_quantity',case when value->>'id'=product::text then 3 else 0 end,'wasted_quantity',case when value->>'id'=product::text then 1 else 0 end,'quantity',case when value->>'id'=product::text then 5 else (value->>'quantity')::integer end)) into payload from jsonb_array_elements(state->'items');
 original:=payload;
 first_saved:=public.save_branch_inventory_day(day,payload,'',null,previous);
 if not exists(select 1 from public.branch_inventory_counts where id=first_saved and submitted_by=actor and submitted_name<>'') then raise exception 'Last updater missing';end if;
 denied:=false;begin perform public.save_branch_inventory_day(day,payload,'',null,previous);exception when others then denied:=sqlerrm like '%Inventory changed%';end;if not denied then raise exception 'Stale update accepted';end if;
 execute 'set local role postgres';
 perform public.submit_pickup(ready_order,jsonb_build_array(jsonb_build_object('line_id',(select id from public.order_lines where order_id=ready_order),'quantity',8)),'',false);
 execute 'set local role authenticated';
 state:=public.branch_inventory_workspace(day);select value into item from jsonb_array_elements(state->'items') where value->>'id'=product::text;
 if (item->>'received_quantity')::integer<>12 or (item->>'quantity')::integer<>13 or not (item->>'needs_review')::boolean then raise exception 'Late pickup not added exactly once';end if;
 denied:=false;begin perform public.save_branch_inventory_day(day,original,'',first_saved,previous);exception when others then denied:=sqlerrm like '%pickups changed%';end;if not denied then raise exception 'Changed receipt snapshot accepted';end if;
 select jsonb_agg(case when value->>'item_id'=product::text then value||jsonb_build_object('expected_received_quantity',12,'quantity',12) else value end) into payload from jsonb_array_elements(payload);
 denied:=false;begin perform public.save_branch_inventory_day(day,payload,'',first_saved,previous);exception when others then denied:=sqlerrm like '%Add a note%';end;if not denied then raise exception 'Unexplained adjustment accepted';end if;
 second_saved:=public.save_branch_inventory_day(day,payload,'Physical count correction',first_saved,previous);
 if (select count(*) from public.branch_inventory_counts where location_id=branch and count_date=day)<>2 then raise exception 'Update history overwritten';end if;
 state:=public.branch_inventory_workspace(day);select value into item from jsonb_array_elements(state->'items') where value->>'id'=product::text;
 if (item->>'quantity')::integer<>12 or (item->>'adjustment_quantity')::integer<>-1 then raise exception 'Correction or adjustment incorrect';end if;
 denied:=false;begin perform public.branch_inventory_workspace(day,other);exception when others then denied:=true;end;if not denied then raise exception 'Cross-branch inventory accessible';end if;
 execute 'set local role postgres';
 update public.profiles set role='BRANCH_EMPLOYEE' where id=actor;
 execute 'set local role authenticated';
 state:=public.branch_inventory_workspace(day);
 perform public.save_branch_inventory_day(day,payload,'Employee update',second_saved,previous);
 if exists(select 1 from public.orders) or exists(select 1 from public.weekly_invoices) then raise exception 'Employee order access expanded';end if;
 execute 'set local role postgres';
 state:=public.inventory_day_state(branch,day+1);select value into item from jsonb_array_elements(state->'items') where value->>'id'=product::text;
 if (item->>'opening_quantity')::integer<>12 then raise exception 'Next-day carry-forward duplicated received stock';end if;
 if (select available_stock from public.catalog_items where id=product) is distinct from stock then raise exception 'Daily stock flow changed central inventory';end if;
end;$$;
rollback;
select 'Passed: previous closing carry-forward, completed-only receipts, late pickups counted once, manager and employee updates, named updater, immutable history, stale-update rejection, adjustment notes, branch isolation and unchanged central stock. Fixtures rolled back.' as result;
